import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Observabilidad","description":"","frontmatter":{},"headers":[],"relativePath":"ia/vllm/06-observabilidad.md","filePath":"ia/vllm/06-observabilidad.md","lastUpdated":1789040978000,"isDraft":false}'),i={name:"ia/vllm/06-observabilidad.md"};function s(l,e,d,n,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="observabilidad" tabindex="-1">Observabilidad <a class="header-anchor" href="#observabilidad" aria-label="Permalink to &quot;Observabilidad&quot;">​</a></h1><p>Un servidor vLLM que “responde a curl” no está operado. El proceso ya expone <strong>Prometheus</strong> en el mismo puerto HTTP, ruta <code>/metrics</code>, con prefijo <code>vllm:</code>. No hace falta un sidecar para empezar.</p><p>Cómo se arranca el servidor está en <a href="./05-despliegue">Despliegue</a>. Qué significan TTFT y KV cache, en <a href="./04-batching-y-rendimiento">Batching</a>.</p><p>Documentación oficial: <a href="https://docs.vllm.ai/en/latest/design/metrics/" target="_blank" rel="noreferrer">métricas</a>, <a href="https://docs.vllm.ai/en/stable/examples/observability/prometheus_grafana/" target="_blank" rel="noreferrer">ejemplo Prometheus/Grafana</a>.</p><h2 id="ver-metricas" tabindex="-1">Ver métricas <a class="header-anchor" href="#ver-metricas" aria-label="Permalink to &quot;Ver métricas&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/metrics</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span></span></code></pre></div><p>Deberías ver texto Prometheus (<code># HELP</code>, <code># TYPE</code>, series <code>vllm:...</code>). Si da 404, no estás contra el <code>vllm serve</code> (o el puerto es otro).</p><p>Nombres útiles (pueden llevar label <code>model_name</code>):</p><table tabindex="0"><thead><tr><th>Métrica</th><th>Tipo</th><th>Para qué</th></tr></thead><tbody><tr><td><code>vllm:num_requests_running</code></td><td>Gauge</td><td>Batch en ejecución.</td></tr><tr><td><code>vllm:kv_cache_usage_perc</code></td><td>Gauge</td><td>Fracción de bloques KV usados.</td></tr><tr><td><code>vllm:prompt_tokens_total</code> / <code>vllm:generation_tokens_total</code></td><td>Counter</td><td>Volumen de tokens.</td></tr><tr><td><code>vllm:request_success_total</code></td><td>Counter</td><td>Peticiones terminadas (razón de fin).</td></tr><tr><td><code>vllm:time_to_first_token_seconds</code></td><td>Histogram</td><td>TTFT.</td></tr><tr><td><code>vllm:inter_token_latency_seconds</code></td><td>Histogram</td><td>Latencia entre tokens.</td></tr><tr><td><code>vllm:e2e_request_latency_seconds</code></td><td>Histogram</td><td>Latencia extremo a extremo.</td></tr></tbody></table><p>Prometheus hace scrape periódico de esa URL. El ejemplo oficial lanza Prometheus/Grafana con Docker y un <code>scrape_configs</code> hacia el puerto 8000. No copies un dashboard de un blog: parte del JSON del repo de vLLM o construye paneles sobre estas series.</p><h2 id="logs-de-peticiones" tabindex="-1">Logs de peticiones <a class="header-anchor" href="#logs-de-peticiones" aria-label="Permalink to &quot;Logs de peticiones&quot;">​</a></h2><p>En la CLI, <code>--enable-log-requests</code> registra peticiones (el detalle depende del nivel de log). <code>--disable-log-stats</code> apaga el resumen periódico. En desarrollo ayuda; en producción con PII, no loguees prompts a disco compartido.</p><h2 id="que-mirar-en-incidente" tabindex="-1">Qué mirar en incidente <a class="header-anchor" href="#que-mirar-en-incidente" aria-label="Permalink to &quot;Qué mirar en incidente&quot;">​</a></h2><ol><li>¿El proceso vive? <code>GET /v1/models</code>.</li><li>¿Hay cola / KV llena? <code>num_requests_running</code>, <code>kv_cache_usage_perc</code>.</li><li>¿TTFT o ITL se fueron? histogramas anteriores.</li><li>¿OOM o restart? métricas a cero y logs del contenedor.</li></ol><p>GPU a nivel de hardware (DCGM, <code>nvidia-smi</code>) complementa; no sustituye las series <code>vllm:</code>.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Scrapear el puerto equivocado o un <code>LLM()</code> offline que no abre HTTP.</li><li>Alertar sobre un counter sin <code>rate()</code>.</li><li>Exponer <code>/metrics</code> a Internet junto con la API.</li><li>Confundir “no hay series” con “el modelo es lento”: primero confirma el scrape.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Un job de Prometheus por instancia de vLLM (label de modelo y host).</li><li>SLOs sobre histogramas (p95 TTFT), no sobre un echo de curl.</li><li>Retención y grabación de deploys (versión de imagen + id de modelo) para correlacionar regresiones.</li><li>El capítulo 7 recoge prácticas de operación más amplias.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Con el servidor arriba, genera tráfico (varios chats) y vuelve a <code>curl /metrics</code>.</li><li>Localiza <code>vllm:generation_tokens_total</code> y comprueba que sube.</li><li>Apunta tres series que usarías en una alerta (KV, cola, TTFT).</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./07-buenas-practicas">Buenas prácticas</a>.</p>',23)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
